files.content:
.root {
  display: inline-flex;
  min-width: 0;
  max-width: 100%;
  flex-shrink: 1;
  border: 1px solid var(--border);
  border-radius: var(--radius-control);
  background: var(--surface-muted);
  user-select: none;
}

.track {
  --fade-start: 0px;
  --fade-end: 0px;
  isolation: isolate;
  display: flex;
  min-width: 0;
  gap: 2px;
  overflow-x: auto;
  overscroll-behavior-x: contain;
  padding: 3px;
  border-radius: inherit;
  scrollbar-width: none;
}

.track::-webkit-scrollbar {
  display: none;
}

.button {
  position: relative;
  display: inline-flex;
  min-height: calc(var(--control-height-sm) + 2px);
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  border: 0;
  border-radius: calc(var(--radius-control) - 3px);
  padding: 0 var(--space-3);
  background: transparent;
  color: var(--text-secondary);
  font: inherit;
  font-size: var(--text-xs);
  font-weight: 500;
  line-height: 1;
  white-space: nowrap;
  cursor: pointer;
  outline: none;
  transition: color var(--duration-fast) var(--ease-standard);
}

.button:hover:not(:disabled) {
  color: var(--foreground);
}

.button[data-selected] {
  color: var(--foreground);
}

.button:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.selection {
  position: absolute;
  inset: 0;
  z-index: -1;
  border-radius: inherit;
  background: var(--surface);
  box-shadow: var(--shadow-resting);
}

:root[data-theme="dark"] .selection {
  background: var(--surface-raised);
  box-shadow: 0 0 0 1px var(--border), 0 1px 3px oklch(0% 0 0 / 0.4);
}

.label {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.accessory {
  display: inline-flex;
  align-items: center;
  font-size: 0.85em;
  opacity: 0.85;
}
